export const code = async (inputs) => {
  const str = (v) => String(v === undefined || v === null ? '' : v).trim();
  const arr = (src) => Array.isArray(src) ? src : (src && Array.isArray(src.records) ? src.records : []);
  const flat = (rec) => {
    const out = {};
    const cells = (rec && rec.cells) || {};
    Object.keys(cells).forEach((fid) => {
      const c = cells[fid];
      if (c && typeof c === 'object' && typeof c.fieldName === 'string') out[c.fieldName] = c.value === undefined || c.value === null ? '' : String(c.value);
    });
    return out;
  };
  const byEvent = {};
  (Array.isArray(inputs.due) ? inputs.due : []).forEach((d) => { if (d && str(d.eventId) !== '') byEvent[str(d.eventId)] = d; });
  // Получатели — только status=registered. Отбор повторяется в коде (Q25):
  // фильтр чтения может разойтись, решение — по полям записи.
  const seen = {};
  const targets = arr(inputs.regs).map(flat)
    .filter((r) => str(r.status) === 'registered' && byEvent[str(r.event_id)] && str(r.telegram_id) !== '')
    .filter((r) => { const k = str(r.event_id) + '|' + str(r.telegram_id); if (seen[k]) return false; seen[k] = true; return true; })
    .map((r) => { const d = byEvent[str(r.event_id)]; return { eventId: str(r.event_id), kind: str(d.kind), telegramId: str(r.telegram_id), title: str(d.title), when: str(d.when), address: str(d.address), mapsUrl: str(d.mapsUrl) }; });
  return { targets: targets, count: targets.length };
};

export const code = async (inputs) => {
  const str = (v) => String(v === undefined || v === null ? '' : v).trim();
  const arr = (src) => Array.isArray(src) ? src : (src && Array.isArray(src.records) ? src.records : []);
  const flat = (rec) => {
    const out = {};
    const cells = (rec && rec.cells) || {};
    Object.keys(cells).forEach((fid) => {
      const c = cells[fid];
      if (c && typeof c === 'object' && typeof c.fieldName === 'string') out[c.fieldName] = c.value === undefined || c.value === null ? '' : String(c.value);
    });
    return out;
  };
  const parse = (s) => { if (!s) return NaN; return Date.parse(/[Zz]$/.test(s) || /[+-][0-9]{2}:?[0-9]{2}$/.test(s) ? s : s + 'Z'); };
  // Показ — Asia/Tashkent временем (OWN-3): окно уже говорит «завтра» / «через
  // два часа» (шаблон remind.24h/remind.2h), дата с годом здесь — шум
  // (W51: было «17 сентября 2026 г. в 17:41»). Форма прототипа: when='18:30'.
  const WHEN_FMT = new Intl.DateTimeFormat('ru-RU', { timeZone: 'Asia/Tashkent', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' });

  // W90 (#142): карта «Как добраться» — только когда координаты заполнены и
  // осмысленны. Пусто/нечисло/вне диапазона/(0,0) — не гео: (0,0) — это
  // Гвинейский залив, а не адрес (баг #124, закрыт в W76). Ссылка не
  // хранится, а собирается из lat/lon (OWN-2).
  const mapsUrlOf = (e) => {
    const latS = str(e.lat);
    const lonS = str(e.lon);
    if (latS === '' || lonS === '') return '';
    const lat = Number(latS);
    const lon = Number(lonS);
    if (!isFinite(lat) || !isFinite(lon)) return '';
    if (lat < -90 || lat > 90 || lon < -180 || lon > 180) return '';
    if (lat === 0 && lon === 0) return '';
    return 'https://yandex.uz/maps/?ll=' + lon + '%2C' + lat + '&z=17&pt=' + lon + '%2C' + lat;
  };

  const H = 3600 * 1000;
  const now = Date.now();
  const due = [];
  arr(inputs.events).map(flat)
    .filter((e) => str(e.status) === 'published' && str(e.id) !== '')
    .forEach((e) => {
      const ms = parse(str(e.starts_at));
      if (!isFinite(ms)) return;
      const dt = ms - now;
      // Окна OWN-16: 24h iff 2h<dt<=24h, 2h iff 0<dt<=2h. В момент старта —
      // ничего; пропущенное окно не досылается (dt<=0 — пропуск навсегда).
      // Событие, опубликованное поздно (dt уже <2h), вид 24h не получит никогда.
      let kind = '';
      if (dt > 2 * H && dt <= 24 * H) kind = '24h';
      else if (dt > 0 && dt <= 2 * H) kind = '2h';
      else return;
      due.push({ eventId: str(e.id), title: str(e.title), startsAt: str(e.starts_at), address: str(e.address), kind: kind, when: WHEN_FMT.format(new Date(ms)), mapsUrl: mapsUrlOf(e) });
    });
  const seen = {};
  const ids = due.map((d) => d.eventId).filter((id) => { if (seen[id]) return false; seen[id] = true; return true; });
  return { nowIso: new Date(now).toISOString(), due: due, dueCount: due.length, dueIdsCsv: ids.length ? ids.join(',') : '__none__' };
};
